const fonte = $('Entrada').item.json.fonte;
const coleta = $('Abrir execução').item.json;
const resultado = $json ?? {};
const removerSegredos = (texto) => String(texto)
  .replace(/(access_token|refresh_token|client_secret|developer_token|api_key|key|token)=[^&\s"']+/gi, '$1=[removido]')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/-]+=*/g, 'Bearer [removido]');
const mensagemDoErro = (erro) => removerSegredos(typeof erro === 'string' ? erro : erro?.message ?? JSON.stringify(erro)).slice(0, 500);
const respostaInvalida = Boolean(resultado.error)
  || !Array.isArray(resultado.linhas)
  || !resultado.volumetria
  || typeof resultado.volumetria !== 'object';
const linhas = respostaInvalida ? [] : resultado.linhas;
const falhas = respostaInvalida
  ? [{ causa: 'falha_coletor', detalhe: resultado.error ? mensagemDoErro(resultado.error) : 'o coletor devolveu uma resposta sem linhas ou volumetria' }]
  : Array.isArray(resultado.falhas) ? resultado.falhas.filter((falha) => falha && falha.causa) : [];
const NAO_FATAIS = new Set(['sem_dados_no_periodo', 'coleta_incompleta']);
const fatal = falhas.find((falha) => !NAO_FATAIS.has(falha.causa)) ?? null;
const incompletas = falhas.filter((falha) => falha.causa === 'coleta_incompleta');
const status = fatal ? 'failed' : incompletas.length > 0 ? 'partial' : 'success';
const detalhes = (lista) => removerSegredos(lista.map((falha) => falha.detalhe ?? falha.causa).join(' | ')).slice(0, 1000);

const qualidadeResumo = {
  fontesEsperadas: 1,
  fontesColetadas: fatal ? 0 : 1,
  faltantes: falhas.slice(0, 500).map((falha) => ({
    fonte: fonte.nome || fonte.externalId,
    causa: String(falha.causa).slice(0, 80),
    detalhe: falha.detalhe == null ? null : removerSegredos(falha.detalhe).slice(0, 500),
  })),
  paridade: [],
  volumetria: respostaInvalida ? { linhas: 0, bytes: 0, requests: 0, duracaoMs: 0 } : resultado.volumetria,
};

return {
  json: {
    coletaId: coleta.id,
    status,
    errorCode: fatal ? fatal.causa : incompletas.length > 0 ? 'coleta_incompleta' : null,
    errorMessage: fatal ? removerSegredos(fatal.detalhe ?? fatal.causa).slice(0, 1000) : incompletas.length > 0 ? detalhes(incompletas) : null,
    requestCount: respostaInvalida ? 0 : resultado.requests ?? 0,
    linhas,
    qualidadeResumo,
  },
};

const { coletaId, linhas } = $input.first().json;
const MAX_LINHAS = 10000;
const MAX_BYTES = 8000000;
const lotes = [];
let atual = [];
let bytes = 0;
for (const linha of linhas) {
  const tamanho = JSON.stringify(linha).length;
  if (atual.length > 0 && (atual.length >= MAX_LINHAS || bytes + tamanho > MAX_BYTES)) {
    lotes.push(atual);
    atual = [];
    bytes = 0;
  }
  atual.push(linha);
  bytes += tamanho;
}
if (atual.length > 0 || lotes.length === 0) lotes.push(atual);
return lotes.map((lote, indice) => ({ json: { coletaId, lote: indice + 1, lotes: lotes.length, linhas: lote }, pairedItem: 0 }));

const fonte = $('Entrada').item.json.fonte;
const coleta = $json;
const temColeta = Boolean(coleta?.id);

const qualidadeResumo = {
  fontesEsperadas: 1,
  fontesColetadas: 0,
  faltantes: [{ fonte: fonte.nome || fonte.externalId, causa: 'sem_credencial', detalhe: 'Conexão sem coletor provisionado no n8n.' }],
  paridade: [],
  volumetria: { linhas: 0, bytes: 0, requests: 0, duracaoMs: 0 },
};

return {
  json: {
    coletaId: temColeta ? coleta.id : null,
    temColeta,
    status: 'failed',
    errorCode: 'sem_credencial',
    errorMessage: 'Conexão sem coletor provisionado no n8n.',
    qualidadeResumo,
  },
};

const qualidade = $('Calcular qualidade').first().json;
const respostas = $input.all().map((item) => item.json ?? {});
const esperadas = qualidade.linhas.length;
const gravadas = respostas.reduce((total, resposta) => total + Number(resposta.linhasGravadas ?? 0), 0);
const descartadas = respostas.reduce((total, resposta) => total + Number(resposta.linhasDescartadas ?? 0), 0);
const recusada = respostas.find((resposta) => resposta.linhasGravadas === undefined);
const chaveInvalida = {};
for (const resposta of respostas) {
  for (const [tabela, quantidade] of Object.entries(resposta.descartesDeChave ?? {})) {
    chaveInvalida[tabela] = (chaveInvalida[tabela] ?? 0) + Number(quantidade ?? 0);
  }
}
const faltantesDeChave = Object.entries(chaveInvalida)
  .filter(([, quantidade]) => quantidade > 0)
  .map(([tabela, quantidade]) => ({ fonte: tabela.slice(0, 120), causa: 'coleta_incompleta', detalhe: `${quantidade} linha(s) com chave inválida descartada(s)` }));
const gravou = qualidade.status === 'success' || qualidade.status === 'partial';
const falhouGravacao = gravou && esperadas > 0 && (Boolean(recusada) || gravadas + descartadas !== esperadas);
const removerSegredos = (texto) => String(texto)
  .replace(/(access_token|refresh_token|client_secret|developer_token|api_key|key|token)=[^&\s"']+/gi, '$1=[removido]')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/-]+=*/g, 'Bearer [removido]');
const detalheDaRecusa = (resposta) => resposta.detail ?? resposta.title
  ?? (resposta.error ? removerSegredos(typeof resposta.error === 'string' ? resposta.error : resposta.error?.message ?? JSON.stringify(resposta.error)) : 'sem detalhe');
const motivo = recusada
  ? `lote recusado: ${detalheDaRecusa(recusada)}`
  : `gravadas ${gravadas} + descartadas ${descartadas} de ${esperadas} em ${respostas.length} lote(s)`;
const rebaixada = !falhouGravacao && qualidade.status === 'success' && faltantesDeChave.length > 0;
const qualidadeResumo = qualidade.qualidadeResumo && faltantesDeChave.length > 0
  ? { ...qualidade.qualidadeResumo, faltantes: [...qualidade.qualidadeResumo.faltantes, ...faltantesDeChave].slice(0, 500) }
  : qualidade.qualidadeResumo;

return [{
  json: {
    coletaId: qualidade.coletaId,
    status: falhouGravacao ? 'failed' : rebaixada ? 'partial' : qualidade.status,
    requestCount: qualidade.requestCount,
    rowsReceived: esperadas,
    rowsWritten: gravadas,
    qualidadeResumo,
    errorCode: falhouGravacao ? 'gravacao_bq' : rebaixada ? 'coleta_incompleta' : qualidade.errorCode,
    errorMessage: falhouGravacao
      ? String(motivo).slice(0, 1000)
      : rebaixada
        ? faltantesDeChave.map((faltante) => `${faltante.fonte}: ${faltante.detalhe}`).join('; ').slice(0, 1000)
        : qualidade.errorMessage,
  },
  pairedItem: 0,
}];

const entrada = $('Entrada').item.json;
const coleta = $json ?? {};
const ok = coleta.status === 'success' || coleta.status === 'partial';
return {
  json: {
    fonteId: entrada.fonte.fonteId,
    platform: entrada.fonte.platform,
    nome: entrada.fonte.nome,
    janela: entrada.janela,
    tentativa: entrada.tentativa,
    ok,
    coletaId: coleta.id ?? null,
    status: coleta.status ?? 'erro_api',
    rowsReceived: coleta.rowsReceived ?? 0,
    rowsWritten: coleta.rowsWritten ?? 0,
    errorCode: coleta.errorCode ?? (ok ? null : coleta.title ?? 'erro_api'),
    errorMessage: coleta.errorMessage ?? (ok ? null : coleta.detail ?? null),
  },
};
